Here is a basic example of a shopping cart component using React and Redux Toolkit. I'll cover how to create a cart reducer, cart actions, and connect the cart to the component.

First, let's set up the cart reducer in `cartSlice.js`:

```javascript
// cartSlice.js
import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
  quantity: 0,
  subtotal: 0.0,
  tax: 0.0,
  total: 0.0,
};

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem(state, action) {
      const { item, quantity } = action.payload;
      state.items = state.items.filter((i) => i.id!== item.id);
      state.items.push({
       ...item,
        quantity,
      });
      state.quantity += quantity;
      state.subtotal += item.price * quantity;
    },
    removeItem(state, action) {
      const { id } = action.payload;
      const index = state.items.findIndex((i) => i.id === id);
      state.items.splice(index, 1);
      state.quantity -= state.items[index].quantity;
      state.subtotal -= state.items[index].price * state.items[index].quantity;
    },
    clearCart(state) {
      state.quantity = 0;
      state.subtotal = 0.0;
      state.tax = 0.0;
      state.total = 0.0;
      state.items = [];
    },
  },
});

export const { addItem, removeItem, clearCart } = cartSlice.actions;
export default cartSlice.reducer;
```

