Here's the full Cart component with a table displaying items and quantity controls, as well as checkout functionality:

```jsx
import React from'react';
import { useSelector, useDispatch } from'react-redux';
import { addItem, removeItem } from './cartSlice';
import { checkout } from './cartSlice';
import { Link } from'react-router-dom';

const Cart = () => {
  const items = useSelector(state => state.cart.items);
  const dispatch = useDispatch();

  const handleAddItem = item => {
    dispatch(addItem(item));
  };

  const handleRemoveItem = item => {
    dispatch(removeItem(item.id));
  };

  const handleCheckout = () => {
    dispatch(checkout());
  };

  return (
    <main>
      <h1>Cart</h1>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Price</th>
            <th>Quantity</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {items.map(item => (
            <tr key={item.id}>
              <td>{item.name}</td>
              <td>${item.price}</td>
              <td>
                <button onClick={() => handleRemoveItem(item)}>X</button>
                <input
                  type="number"
                  value={item.quantity}
                  onChange={e => {
                    item.quantity = parseInt(e.target.value);
                  }}
                />
                <button onClick={() => handleAddItem(item)}>+</button>
              </td>
              <td>
                <button
                  onClick={() => {
                    const isConfirmed = window.confirm(
                      'Are you sure you want to remove this item?'
                    );
                    if (isConfirmed) {
                      handleRemoveItem(item.id);
                    }
                  }}
                >
                  Remove
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <p>Total: {items.reduce((sum, item) => sum + item.price * item.quantity, 0)}</p>
      <button onClick={handleCheckout}>Checkout</button>
      <p>
        <Link to="/">Back to Catalog</Link>
      </p>
    </main>
  );
};

export default Cart;
```

