Here's the React CartComponent that integrates with our `cartSlice` created earlier. This component fetches items from the cart state, renders them, and handles quantity changes and item removals.

```jsx
import React from'react';
import { useSelector, useDispatch } from'react-redux';
import { addQuantity, removeItem, addItem } from './cartSlice';
import { removeItemFromCart, calculateTotal } from './cartSlice';
import { Item } from './Item';

const CartComponent = () => {
  const cart = useSelector(state => state.cart.items);
  const dispatch = useDispatch();

  const handleQuantityChange = (id, quantity) => {
    dispatch(addQuantity({ id, quantity }));
  };

  const handleRemoveItem = (id) => {
    dispatch(removeItem(id));
  };

  const checkout = () => {
    // implement your own checkout flow, or call a payment API
    alert("Checkout initiated");
  };

  return (
    <div>
      <h1>Shopping Cart</h1>
      <ul>
        {cart.length === 0 && <p>No items in cart.</p>}
        {cart.map(i => (
          <li key={i.id}>
            <Item item={i} onQuantityChange={handleQuantityChange} onRemove={handleRemoveItem} />
          </li>
        ))}
      </ul>
      <p>Total: ${calculateTotal(cart)}</p>
      <button onClick={checkout}>Checkout</button>
    </div>
  );
};

export default CartComponent;
```

This component fetches the cart items from the Redux state and uses the cart actions in this slice to update quantity. Note we're injecting the `removeItem` action directly because `removeItem` is currently an untyped reducer function in the cart slice. But this will work until we create a reducer function for it.

